{
  "propositions": [
    {
      "id": "P1",
      "proposition": "Each LEA director of schools and public charter school director must annually designate one instructional day each school year to observe the Fourth of July by providing K–12 students age- and grade-appropriate instruction on the founding of the United States, the original thirteen colonies' separation from Great Britain, the Declaration of Independence, the United States Constitution, and American citizens' fundamental rights and freedoms.",
      "importance": "core",
      "section": "SECTION 1(b), (e)(1)",
      "source_quote": "shall annually designate for the LEA or public charter school one (1) instructional"
    },
    {
      "id": "P2",
      "proposition": "Each LEA and public charter school must determine the instructional program and methods for the required instruction, which may include interactive classroom lessons, readings, writing assignments, discussions, or school assemblies; the instruction must accomplish the prescribed grade-specific objectives.",
      "importance": "supporting",
      "section": "SECTION 1(c)",
      "source_quote": "Each LEA and public charter school shall determine the instructional program"
    },
    {
      "id": "P3",
      "proposition": "For grades K–5, the instruction must introduce foundational concepts of American independence so students can explain the Fourth of July's meaning, identify the United States as an independent nation, describe basic ideas of freedom and individual rights, and recognize national symbols and their connection to American freedom and independence.",
      "importance": "core",
      "section": "SECTION 1(d)(1)",
      "source_quote": "Introduce the foundational concepts of American independence to"
    },
    {
      "id": "P4",
      "proposition": "For grades 6–8, the instruction must emphasize the Fourth of July's historical context and establish civic understanding, which may be accomplished through the social studies curriculum. Students must be able to describe events leading to independence from Great Britain, explain why the original thirteen colonies sought self-governance, summarize the purpose and significance of the Declaration of Independence and United States Constitution, and identify liberty, individual rights, limited government, and consent of the governed as foundational civic principles.",
      "importance": "core",
      "section": "SECTION 1(d)(2)",
      "source_quote": "Emphasize the historical context of the Fourth of July and establish a"
    },
    {
      "id": "P5",
      "proposition": "For grades 9–12, the instruction must focus on analysis of foundational texts and civic themes, which may be accomplished through the English language arts curriculum. Students must be able to analyze the Declaration of Independence and United States Constitution as foundational texts; identify American Revolution themes including liberty, equality, and natural rights; evaluate the historical and philosophical significance of American independence; and understand founding principles' connection to modern civic responsibilities and American citizenship.",
      "importance": "core",
      "section": "SECTION 1(d)(3)",
      "source_quote": "Focus on analysis of foundational texts and civic themes for students"
    },
    {
      "id": "P6",
      "proposition": "Each LEA director of schools and public charter school director must ensure consistent implementation at each school in the LEA or at the charter school and provide guidance as needed to support implementation.",
      "importance": "supporting",
      "section": "SECTION 1(e)(2), (4)",
      "source_quote": "Ensure consistent implementation of this section at each school in the"
    },
    {
      "id": "P7",
      "proposition": "Each LEA director of schools and public charter school director must verify that the instruction at each public school in the LEA or at the charter school complies with the section's requirements and, when provided as part of a social studies or English language arts class, aligns with relevant state academic standards adopted by the state board of education.",
      "importance": "supporting",
      "section": "SECTION 1(e)(3)",
      "source_quote": "Verify that the instruction provided to students at each public school"
    },
    {
      "id": "P8",
      "proposition": "The required instruction must be nonpartisan and solely educational, focusing at all times on historical facts, the founding documents' content, and the civic principles underlying the creation of those documents and the United States.",
      "importance": "core",
      "section": "SECTION 1(f)",
      "source_quote": "nonpartisan and solely educational in nature."
    },
    {
      "id": "P9",
      "proposition": "Each LEA and public charter school must periodically review the instruction's content, materials, and methods and update them as it determines appropriate to implement best practices in civic education and ensure that instruction provided as part of social studies or English language arts classes aligns with relevant state academic standards adopted by the state board of education.",
      "importance": "supporting",
      "section": "SECTION 1(g)",
      "source_quote": "Each LEA and public charter school shall periodically review the content,"
    },
    {
      "id": "P10",
      "proposition": "The act takes effect upon becoming law and applies beginning with the 2026–2027 school year and every school year thereafter.",
      "importance": "core",
      "section": "SECTION 2",
      "source_quote": "and applies to the 2026-2027 school year and each school year thereafter."
    }
  ]
}
